node -e "
const s=require('./data/2026-11-06.script.json');
const intro=s.blocks.find(b=>b.type==='intro');
intro.lines.forEach(l=>console.log(l.host+': '+l.text));
console.log('--- OUTRO ---');
const o=s.blocks.find(b=>b.type==='outro');
o.lines.forEach(l=>console.log(l.host+': '+l.text));
console.log('--- blocks:', s.blocks.length, 'words:', JSON.stringify(s).split(/\s+/).length);
"

for f in 2026-11-05 2026-11-04 2026-11-03; do echo "=== $f ==="; node -e "
const s=require('./data/$f.script.json');
const intro=s.blocks.find(b=>b.type==='intro');
intro.lines.slice(0,8).forEach(l=>console.log(l.text));
" 2>/dev/null | grep -i epilogue; done

