          "headline": "Nvidia's board opens an independent investigation after reports Jensen Huang was a foreign-intelligence target",
          "sources": [
            { "name": "NVIDIA", "url": "https://nvidianews.nvidia.com/news/statement-from-nvidia-board-of-directors" },
            { "name": "CNBC", "url": "https://www.cnbc.com/2026/11/08/nvidia-jensen-huang-investigation-china-spy.html" },
